import numpy as np

bg = 8
h, w = grid.shape

# Look for patterns: which rows have how many objects of each color?
from collections import Counter

row_data = {}
for r in range(h):
    row_objs = []
    for c in range(w):
        if grid[r, c] != bg:
            val = int(grid[r, c])
            row_objs.append(val)
    row_data[r] = Counter(row_objs)

print("Objects per row by value:")
for r in range(h):
    counts = dict(row_data.get(r, Counter()))
    print(f"Row {r}: {counts}")

# Maybe each output cell position is determined by its index alone?
# Like: the k-th non-background cell (in some order) gets value floor(k/9)+1 or something

all_positions = []
for r in range(h):
    for c in range(w):
        if grid[r, c] != bg:
            all_positions.append((r * w + c, int(grid[r, c])))

print("\nPositions and values (0-indexed within flattened array):")
for idx, (pos, val) in enumerate(all_positions):
    print(f"Index {idx}: pos=({pos//w},{pos%w}), val={val}")

# Check if value correlates with index in any simple way
values_flat = [v for _, v in all_positions]
print(f"\nAll values in order: {values_flat}")

